from __future__ import annotations; from datetime import UTC, date, datetime; from decimal import Decimal; import pytest; from src.pricing.base.errors import InvalidObservationError, InvalidSubjectError; from src.pricing.base.observation import Authority, ObservationSource, PriceObservation; from src.pricing.base.policy import ResolutionPolicy; from src.pricing.base.subject import PriceableSubject, SubjectKind
def test_currency_pair_builds_a_slash_separated_upper_cased_key():
    subject = PriceableSubject.currency_pair('usd', 'sgd'); assert subject.kind is SubjectKind.CURRENCY_PAIR; assert subject.key == 'USD/SGD'
    with pytest.raises(InvalidSubjectError): PriceableSubject(SubjectKind.CURRENCY_PAIR, 'USDSGD')
    with pytest.raises(InvalidSubjectError): PriceableSubject(SubjectKind.CURRENCY_PAIR, 'US1/SGD')
    assert PriceableSubject.security('AAPL') == PriceableSubject(SubjectKind.SECURITY, 'AAPL'); assert PriceableSubject.component('property') == PriceableSubject(SubjectKind.COMPONENT, 'property')
    with pytest.raises(InvalidSubjectError): PriceableSubject.security('')
    with pytest.raises(InvalidSubjectError): PriceableSubject.component('   ')
    _m5_primary = PriceableSubject.security('9988.HK'); _m5_secondary = PriceableSubject.security('BABA'); assert _m5_primary != _m5_secondary; assert PriceableSubject.security('AAPL') == PriceableSubject.security('AAPL'); _m7_policy = ResolutionPolicy(); assert _m7_policy.max_age_days is None; assert _m7_policy.min_authority is Authority.CRAWLER; assert Authority.OVERRIDE > Authority.MANUAL > Authority.STATEMENT > Authority.CRAWLER
    with pytest.raises(InvalidObservationError): PriceObservation(subject=PriceableSubject.security('AAPL'), value=1.5, as_of=date(2026, 6, 1), observed_at=datetime(2026, 6, 1, 12, tzinfo=UTC), source=ObservationSource.CRAWLER, authority=Authority.CRAWLER)
    with pytest.raises(InvalidObservationError): PriceObservation(subject=PriceableSubject.security('AAPL'), value=Decimal('0'), as_of=date(2026, 6, 1), observed_at=datetime(2026, 6, 1, 12, tzinfo=UTC), source=ObservationSource.CRAWLER, authority=Authority.CRAWLER)
    with pytest.raises(InvalidObservationError): PriceObservation(subject=PriceableSubject.security('AAPL'), value=Decimal('NaN'), as_of=date(2026, 6, 1), observed_at=datetime(2026, 6, 1, 12, tzinfo=UTC), source=ObservationSource.CRAWLER, authority=Authority.CRAWLER)
    with pytest.raises(InvalidObservationError): PriceObservation(subject=PriceableSubject.security('AAPL'), value=Decimal('100'), as_of=date(2026, 6, 1), observed_at=datetime(2026, 6, 1, 12), source=ObservationSource.CRAWLER, authority=Authority.CRAWLER)
    _m13_observation = PriceObservation(subject=PriceableSubject.security('AAPL'), value=Decimal('100'), as_of=date(2026, 1, 1), observed_at=datetime(2026, 6, 1, 12, tzinfo=UTC), source=ObservationSource.STATEMENT, authority=Authority.STATEMENT); assert _m13_observation.as_of < _m13_observation.observed_at.date()
